#!/usr/bin/env bash
#
# COMPILE THE ANDROID `:app` MODULE ON A PULL REQUEST, AND PROVE IT WAS COMPILED.
#
# WHAT THIS EXISTS FOR. `lib/ceiling.sh` (`ceiling_gate_for_ref`) refused every Gradle update to
# `frontend/src-tauri/gen/android` because nothing on a pull request configured `:app`: only
# `android.yml` built it, at release time. A bump of the wrapper, AndroidX or Firebase there could
# therefore break the APK and be found by a release. This is the gate that sees it fail.
#
# WHY `:app` WAS NOT BUILT HERE BEFORE, and what replaces each obstacle (no secret is read):
#   - `tauri.settings.gradle` and `app/tauri.build.gradle.kts` are GENERATED by the app crate's
#     `build.rs` (`tauri_build::mobile::generate_gradle_files`) when `TAURI_ANDROID_PROJECT_PATH`
#     is set, from the `DEP_*_ANDROID_LIBRARY_PATH` each plugin's build script exports. So a
#     `cargo check` for the Android target is the SAME generator `tauri android build` runs, not a
#     second copy of it. Only the build scripts matter; nothing is linked.
#   - `google-services.json` is a secret. `gen/android/ci/google-services.compile-stub.json` is a
#     committed stub with fake values, enough for the plugin to configure the module.
#   - `frontendDist` (`../build`) must exist for the Tauri context macro; an empty page stands in.
#
# THE RUN IS NOT THE ASSERTION. A Gradle invocation that matches no task exits 0 having built
# nothing (the same trap `android-unit-tests.sh` documents), so this reads the output and fails
# unless EACH of the four tasks below actually executed. They are where a dependency bump breaks:
#   - `checkArm64DebugAarMetadata`   an AndroidX release demanding a newer compileSdk or AGP;
#   - `processArm64DebugMainManifest` a manifest merge conflict between the app and a library;
#   - `compileArm64DebugKotlin`       an API a library removed;
#   - `mergeArm64DebugResources`      a `strings.xml` aapt2 refuses (a bare apostrophe: the
#                                     1.6.3-alpha.3 Play build failed on one, #2945 had passed here
#                                     because nothing above merges resources).
#
# THE REAL `google-services.json` IS NEVER OVERWRITTEN. A developer's copy of that git-ignored file
# is not recoverable from git, so this refuses to run when one is present that is not the stub.
#
# THE NDK IS THE RUNNER'S: `android.yml` pins none either - `tauri android build` reads the
# ANDROID_NDK_HOME the runner image provides - so there is no second version to read and no
# fallback variable here; an unset ANDROID_NDK_HOME is an error.
#
# `ANDROID_GRADLE_DIR` and `CARGO` exist for `tests/android-app-compile.test.sh` and nothing else.
#
# Needs: a JDK 21, rustup with the aarch64-linux-android and armv7-linux-androideabi targets, the Android SDK and NDK
# (ANDROID_HOME, ANDROID_NDK_HOME). Usage: bash .github/scripts/android-app-compile.sh
set -euo pipefail

root="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
android="${ANDROID_GRADLE_DIR:-$root/frontend/src-tauri/gen/android}"
cargo_bin="${CARGO:-cargo}"
log="$(mktemp)"

: "${ANDROID_HOME:?ANDROID_HOME is not set - the Android SDK is required}"
: "${ANDROID_NDK_HOME:?ANDROID_NDK_HOME is not set - the C build scripts of the crates need the NDK toolchain}"
ndk="$ANDROID_NDK_HOME"
bin="$ndk/toolchains/llvm/prebuilt/linux-x86_64/bin"

echo "== 1. generate tauri.settings.gradle with the app crate's own build script"
mkdir -p "$root/frontend/build"
[ -e "$root/frontend/build/index.html" ] || echo '<!doctype html><title>compile check</title>' > "$root/frontend/build/index.html"
(
  cd "$root/frontend/src-tauri"
  export TAURI_ANDROID_PROJECT_PATH="$android"
  # What the tauri CLI exports around the same build: with the project path set, `tauri`'s build
  # script rewrites `app/proguard-tauri.pro` for this package and refuses to run without it. The
  # kotlin files wry would generate are committed, so WRY_ANDROID_KOTLIN_FILES_OUT_DIR stays unset.
  export TAURI_ANDROID_PACKAGE_UNESCAPED=fr.emse.canari
  export WRY_ANDROID_PACKAGE=fr.emse.canari
  export WRY_ANDROID_LIBRARY=mines_app_lib
  export CC_aarch64_linux_android="$bin/aarch64-linux-android24-clang"
  export AR_aarch64_linux_android="$bin/llvm-ar"
  export CARGO_TARGET_AARCH64_LINUX_ANDROID_LINKER="$bin/aarch64-linux-android24-clang"
  "$cargo_bin" check --locked --lib --target aarch64-linux-android
  # THE 32-BIT PHONE (2026-11-21). Releases ship armeabi-v7a too (#3932), and a change that only
  # breaks that target (a `usize`/`u32` assumption, a 64-bit atomic) would otherwise surface at
  # release. A `cargo check` like the line above: no link, no APK. The NDK names its 32-bit clang
  # `armv7a-linux-androideabi24-clang`, while the Rust target says `armv7-linux-androideabi`.
  export CC_armv7_linux_androideabi="$bin/armv7a-linux-androideabi24-clang"
  export AR_armv7_linux_androideabi="$bin/llvm-ar"
  export CARGO_TARGET_ARMV7_LINUX_ANDROIDEABI_LINKER="$bin/armv7a-linux-androideabi24-clang"
  "$cargo_bin" check --locked --lib --target armv7-linux-androideabi
)
for f in tauri.settings.gradle app/tauri.build.gradle.kts; do
  [ -s "$android/$f" ] || { echo "::error::$f was not generated - the Rust build script did not run for the Android target"; exit 1; }
done
grep -q "tauri-plugin-" "$android/tauri.settings.gradle" \
  || { echo "::error::tauri.settings.gradle lists no plugin - the DEP_*_ANDROID_LIBRARY_PATH variables were not seen"; exit 1; }

echo "== 2. stub google-services.json (fake values, never the secret)"
stub="$android/ci/google-services.compile-stub.json"
target="$android/app/google-services.json"
if [ -e "$target" ] && ! cmp -s "$stub" "$target"; then
  echo "::error::$target exists and is not the compile stub. It may be the real file, which is not in git and which this script will not overwrite. Move it aside and run again."
  exit 1
fi
cp "$stub" "$target"

tasks=(:app:checkArm64DebugAarMetadata :app:processArm64DebugMainManifest :app:compileArm64DebugKotlin :app:mergeArm64DebugResources)
echo "== 3. configure and run ${tasks[*]}"
(cd "$android" && ./gradlew --no-daemon --console=plain "${tasks[@]}") 2>&1 | tee "$log"

for t in "${tasks[@]}"; do
  # `> Task :app:x` alone means it executed; UP-TO-DATE, FROM-CACHE, NO-SOURCE and SKIPPED each
  # follow it on the same line and each means nothing was checked by THIS run.
  if ! grep -qE "^> Task ${t}$" "$log"; then
    echo "::error::${t} did not execute - a green build that did not run it is not a gate"
    exit 1
  fi
done
echo "OK ${tasks[*]} ran and succeeded"

# THE RELEASE'S DEPENDENCIES MUST BE IN THE CACHE THIS JOB SAVES (2026-11-25). The tasks above are
# all DEBUG, so the cache they fill lacked what only a release links, and a release that restored it
# (a key hit) still went to Maven Central for `error_prone_annotations` and met a 429 - in
# `mergeUniversalReleaseNativeLibs`, the android-jni transform over the release runtime classpath.
# So run the REAL release chain minus rust: `assembleUniversalRelease` and `bundleUniversalRelease`
# (R8, the resource shrinker, packaging, bundletool, signing), then again `--offline`,
# which reaches no network and fails if any of it needs something not in ~/.gradle. A task that is
# up to date still resolves its inputs, so the offline pass is a real resolution. What it cannot see
# is a restore (the job just filled the cache it reads): it proves the chain needs nothing the cache
# does not hold.
#   - `-x rustBuild*Release`: they build native code this gate does not need.
#   - A STUB `libstub.so` in `jniLibs`, so the native-libs merge has an input and its transform runs
#     (it is NO-SOURCE, and resolves nothing, without one). Never committed, removed on exit.
#   - A THROWAWAY keystore and `keystore.properties` (made here by `keytool`, no secret): the release
#     signing config needs a store, and signing is part of what a release runs. A real
#     `keystore.properties` is never overwritten, like the real `google-services.json` above.
# cicd.md#the-android-release-build-resolves-from-a-cache-ci-completes-and-proves-offline-2026-11-25
props="$android/keystore.properties"
stub_dir="$android/app/src/main/jniLibs/arm64-v8a"
stub_so="$stub_dir/libstub.so"
if [ -e "$props" ] || [ -e "$stub_so" ]; then
  echo "::error::$props or $stub_so already exists - this script will not overwrite what may be real. Move it aside and run again."
  exit 1
fi
ks_dir="$(mktemp -d)"
cleanup_release_stubs() { rm -rf "$ks_dir" "$props" "$stub_so"; rmdir "$stub_dir" "$android/app/src/main/jniLibs" 2>/dev/null || true; }
trap cleanup_release_stubs EXIT
"${KEYTOOL:-keytool}" -genkeypair -keystore "$ks_dir/throwaway.jks" -storepass ci-throwaway -keypass ci-throwaway \
  -alias ci -keyalg RSA -keysize 2048 -validity 2 -dname "CN=ci throwaway" > /dev/null 2>&1 \
  || { echo "::error::keytool could not make the throwaway keystore"; exit 1; }
printf 'keyAlias=ci\nkeyPassword=ci-throwaway\nstorePassword=ci-throwaway\nstoreFile=%s\n' "$ks_dir/throwaway.jks" > "$props"
mkdir -p "$stub_dir"
printf 'stub' > "$stub_so"

# Resolve-and-run tasks: each must EXECUTE on the online pass (NO-SOURCE, SKIPPED, UP-TO-DATE mean
# nothing was resolved by THIS run) and must at least appear on the offline pass.
release_tasks=(
  :app:checkUniversalReleaseAarMetadata :app:checkUniversalReleaseDuplicateClasses
  :app:processUniversalReleaseMainManifest :app:mergeUniversalReleaseNativeLibs
  :app:minifyUniversalReleaseWithR8 :app:assembleUniversalRelease :app:bundleUniversalRelease
)
skip_rust=(-x rustBuildUniversalRelease -x rustBuildArmRelease -x rustBuildArm64Release)
for mode in online offline; do
  flag=()
  if [ "$mode" = offline ]; then
    # THE OUTPUTS GO, THE GRADLE CACHES STAY: otherwise every task is UP-TO-DATE and only its inputs are
    # fingerprinted. Removing the app build dir makes each task ACTION run again, from ~/.gradle alone.
    rm -rf "$android/app/build"
    flag=(--offline)
  fi
  echo "== 4. run the release chain (${mode}): ${release_tasks[*]}"
  (cd "$android" && ./gradlew --no-daemon --console=plain "${flag[@]}" "${skip_rust[@]}" "${release_tasks[@]}") 2>&1 | tee "$log" \
    || { echo "::error::the release chain failed ($mode)"; exit 1; }
  if grep -qE "^[[:space:]]*> Could not " "$log"; then
    echo "::error::Gradle reported a resolution problem ($mode)"; exit 1
  fi
  for t in "${release_tasks[@]}"; do
    grep -qE "^> Task ${t}$" "$log" \
      || { echo "::error::${t} did not execute ($mode) - a green build that did not run it resolved nothing"; exit 1; }
  done
  echo "OK the release chain ran ($mode)"
done
# THE JAR THAT FAILED A RELEASE, ASKED FOR BY NAME: any version, so a dependency bump does not break this.
gradle_home="${GRADLE_USER_HOME:-$HOME/.gradle}"
if ! compgen -G "$gradle_home/caches/modules-2/files-2.1/com.google.errorprone/error_prone_annotations/*/*/*.jar" > /dev/null; then
  echo "::error::error_prone_annotations is not in $gradle_home - the release runtime classpath was not downloaded"
  exit 1
fi
echo "OK error_prone_annotations is in the Gradle cache"

# THE RUST TASKS MUST BE REAL. The tauri CLI compiles only the FIRST target itself; every other ABI
# is built by Gradle's `rustBuild<Arch><Profile>` task, which must be a `BuildTask` that runs
# `tauri android android-studio-script`. They were empty `DefaultTask`s from 2026-04 to 2026-11 and
# every release shipped arm64 only, with nothing red. This gate never RUNS them (it would build the
# whole app), so it asks Gradle what each one IS. cicd.md#the-android-release-build-packages-both-abis-because-gradle-builds-them-2026-11-21
for t in rustBuildArmDebug rustBuildArmRelease rustBuildArm64Release; do
  type_out="$(cd "$android" && ./gradlew --no-daemon --console=plain -q ":app:help" --task "$t" 2>&1)" || {
    echo "$type_out"; echo "::error::Gradle does not know :app:${t}"; exit 1; }
  if ! grep -qE "^[[:space:]]+BuildTask \(" <<<"$type_out"; then
    echo "$type_out"
    echo "::error:::app:${t} is not a BuildTask - the 32-bit library would never be built (buildSrc/.../BuildTask.kt, RustPlugin.kt)"
    exit 1
  fi
done
echo "OK rustBuildArmDebug, rustBuildArmRelease and rustBuildArm64Release are BuildTasks"
